import json
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist','--allow-file-access-from-files'])
    pg=b.new_page(viewport={'width':390,'height':780},device_scale_factor=1)
    logs=[]; pg.on('console',lambda m:logs.append(m.type+': '+m.text)); pg.on('pageerror',lambda e:logs.append('PAGEERROR '+str(e)))
    pg.goto('file:///home/claude/space/out/index.html'); pg.wait_for_timeout(1500)
    pg.get_by_text('Новая игра').first.click(); pg.wait_for_timeout(400); pg.get_by_text('Песочница').first.click(); pg.get_by_text('Начать').first.click(); pg.wait_for_timeout(3500)
    pg.get_by_text('Ангар').first.click(); pg.wait_for_timeout(1200); pg.get_by_text('Шаблоны').first.click(); pg.wait_for_timeout(400)
    pg.evaluate("[...document.querySelectorAll('.ptile')].find(e=>e.textContent.includes('Луноход')).click()"); pg.wait_for_timeout(800)
    r=pg.evaluate("""(()=>{const {Builder:B,Gfx}=__T(); const sp=B.D.parts.filter(p=>p.defId==='solar_small'); const s=sp[1]; B.select(s); const a=B.scr(s.x,s.y); const bt=B.D.parts.find(p=>p.defId==='batt_m'); const t=B.scr(bt.x,bt.y); return JSON.stringify({sx:a[0]*Gfx.scale,sy:a[1]*Gfx.scale,tx:t[0]*Gfx.scale,ty:t[1]*Gfx.scale,x0:s.x,y0:s.y,n:B.D.parts.length})})()""")
    print(r); d=json.loads(r)
    print('EL',pg.evaluate("(()=>{const e=document.elementFromPoint(243,423);return e.tagName+'#'+e.id+'.'+e.className})()"))
    # перетащить правую панель немного вверх-вправо (должна прилипнуть обратно к батарее или встать у кабины)
    pg.mouse.move(d['sx'],d['sy']); pg.mouse.down(); pg.mouse.move(d['sx']+20,d['sy']-40,steps=8); pg.wait_for_timeout(200); pg.screenshot(path='out/m0.png')
    print(pg.evaluate("(()=>{const {Builder:B}=__T(); const dr=B.drag; return JSON.stringify({mode:dr&&dr.mode,moved:dr&&dr.moved,snap:dr&&dr.snap&&{t:dr.snap.type,bad:dr.snap.bad,q:dr.snap.q.defId}})})()"))
    pg.mouse.up(); pg.wait_for_timeout(500)
    print(pg.evaluate("""(()=>{const {Builder:B,validateDesign}=__T(); const s=B.sel; return JSON.stringify({sel:s.defId,x:+s.x.toFixed(2),y:+s.y.toFixed(2),issues:validateDesign(B.D.parts,B.W,{}).issues.map(i=>i.text)})})()"""))
    for l in logs[:8]: print(l)
    b.close()
